import subprocess
from Quartz import (
    AXUIElementCreateApplication,
    AXUIElementCopyAttributeValue,
    kAXWindowsAttribute,
    kAXFocusedWindowAttribute,
    kAXChildrenAttribute,
    AXUIElementPerformAction,
    kAXPressAction,
    kAXTitleAttribute,
    kAXDescriptionAttribute,
    kAXRoleAttribute,
)

def find_simulator_process():
    """Find the Simulator process ID"""
    result = subprocess.run(
        ['pgrep', '-f', 'Simulator'],
        capture_output=True,
        text=True
    )
    if result.stdout.strip():
        return int(result.stdout.strip().split('\n')[0])
    return None

def find_button_recursively(element, button_title, depth=0):
    """Recursively search for a button with the given title"""
    if depth > 5:  # Limit recursion depth
        return None

    try:
        # Check element's title
        try:
            title = AXUIElementCopyAttributeValue(element, kAXTitleAttribute, None)
            if title and button_title.lower() in str(title).lower():
                return element
        except:
            pass

        # Check children
        try:
            children_attr = AXUIElementCopyAttributeValue(element, kAXChildrenAttribute, None)
            if children_attr:
                for child in children_attr:
                    result = find_button_recursively(child, button_title, depth + 1)
                    if result:
                        return result
        except:
            pass
    except:
        pass

    return None

# Find Simulator process
sim_pid = find_simulator_process()
if not sim_pid:
    print("Simulator process not found")
else:
    print(f"Found Simulator PID: {sim_pid}")

    try:
        # Create AXUIElement for the Simulator app
        app_element = AXUIElementCreateApplication(sim_pid)

        # Try to find the Open button
        open_button = find_button_recursively(app_element, "Open")

        if open_button:
            print("Found Open button!")
            # Try to press it
            try:
                result = AXUIElementPerformAction(open_button, kAXPressAction)
                print(f"Pressed Open button, result: {result}")
            except Exception as e:
                print(f"Error pressing button: {e}")
        else:
            print("Open button not found")
    except Exception as e:
        print(f"Error: {e}")
PYTHON_EOF

